"""Whole-file readings: small utilities with nontrivial caller contracts."""
ROWS=[]


def add(path,title,intro,principle,use,sections,questions):
    ROWS.append(dict(path=path,title=title,intro=intro,principle=principle,use=use,
                     area='커널 공통 도구 · 상태·수명·경계',sections=sections,questions=questions))


add('lib/clz_tab.c','비트 길이 표 전체: __clz_tab의 이름과 실제 값',
    '파일 이름에 clz가 있다고 해서 배열 값이 바로 선행 0의 개수인 것은 아닙니다. 모든 원소의 수학적 규칙을 확인합니다.',
    '__clz_tab은 256개 unsigned char 상수입니다. 인덱스 0은 0이고 양수 x는 floor(log2(x))+1, 즉 x를 표현하는 최소 비트 수입니다. 표에는 함수나 런타임 초기화가 없습니다.',
    '조회 인덱스는 0..255여야 합니다. 8비트 값의 선행 0 수가 필요하면 8-tab[x]로 변환할 수 있지만, 더 넓은 정수의 전체 선행 0 수는 상위 바이트 처리까지 필요합니다.',
    [('파일 전체 구성과 수열','SPDX 한 줄과 배열 정의 하나가 전체입니다. 0,1,2,2,3,3,3,3처럼 2의 거듭제곱 경계마다 값이 1 증가합니다. [128,255]는 모두 8입니다. const는 읽기 전용 표라는 의도이며 unsigned char는 각 값 0..8을 담기에 충분합니다.'),
     ('계산 예제','tab[0]=0, tab[1]=1, tab[7]=3, tab[8]=4, tab[255]=8입니다. 따라서 8비트 7의 선행 0은 8-3=5개입니다. 0은 이 표에서 명시적으로 0을 갖기 때문에 같은 변환을 하면 8이 됩니다. 0에 대한 일부 CPU clz 명령·컴파일러 builtin의 계약과 이 표의 계약을 혼동하면 안 됩니다.'),
     ('CS와 경계','로그 함수 대신 256바이트 표를 조회하는 시간·공간 절충입니다. lookup O(1)만으로 호출자 전체 알고리즘도 O(1)이라고 일반화하지 않습니다. 배열 자체에는 범위 검사·심볼 export 매크로·할당 함수가 없습니다. 큰 정수를 그대로 인덱스로 쓰면 범위를 벗어납니다.')],
    [('__clz_tab[8]의 값은?', '4', '선행 0의 수인 4를 항상 직접 저장한다', '값 8의 이진 표현 1000은 네 비트여서 4입니다. 이 예에서는 8비트 선행 0 수도 우연히 4이므로 일반 규칙을 착각하기 쉽습니다. 인덱스 1은 tab[1]=1이지만 선행 0은 7입니다.'),
     ('8비트 값 7의 선행 0 수를 이 표로 계산하면?', '8-3=5', 'tab[7]=3', '표는 비트 길이 3을 저장합니다. 전체 폭 8에서 이를 빼야 선행 0의 개수가 나옵니다.'),
     ('256을 직접 배열 인덱스로 사용해도 되는가?', '아니다. 유효 인덱스는 0..255다', '그렇다. 최대 비트 길이 9를 자동 반환한다', '수열의 수학적 패턴이 계속될 수 있어도 실제 배열은 256개 원소뿐입니다. 메모리 객체의 경계는 수학적 확장과 별개입니다.')])

add('lib/bust_spinlocks.c','Oops 출력 보조 전체: 잠금 해제라는 이름 뒤의 카운터',
    '오류 보고 중 콘솔 출력이 막히지 않게 하는 일반 구현입니다. 역사적 이름보다 현재 함수 본문이 실제로 무엇을 바꾸는지 읽습니다.',
    'yes가 0이 아니면 oops_in_progress를 증가시킵니다. yes가 0이면 먼저 console_unblank()를 호출하고 카운터를 감소시켜 0이 된 경우만 wake_up_klogd()를 호출합니다.',
    '진입·종료는 올바르게 짝지어야 합니다. 이 함수는 임의의 spinlock 주소를 받아 모두 unlock하는 함수가 아니며 카운터를 자동으로 0 이상으로 제한하지 않습니다.',
    [('전체 파일과 의존성','SPDX와 일반 fallback 역할의 주석 뒤에 kernel/printk/spinlock/tty/wait/vt_kern/console 헤더를 포함합니다. 이 파일의 유일한 함수는 bust_spinlocks입니다. 실제 본문은 오류 진행 카운터와 콘솔·로그 작업을 제어하며 직접 spin_unlock 호출은 없습니다.'),
     ('중첩 진입 추적','처음 카운터 0에서 yes=1 두 번이면 2입니다. 종료 첫 호출은 console_unblank 후 1이 되어 wake_up_klogd를 부르지 않습니다. 두 번째 종료는 다시 unblank 후 0이 되어 로그 작업을 깨웁니다. 즉 화면 복구 호출과 로그 깨움 조건은 서로 다릅니다.'),
     ('CS 연결과 잘못된 호출','참조 카운터와 비슷한 중첩 상태 표현이지만 이 파일은 원자 참조 카운터 API를 사용하지 않습니다. 모든 호출 문맥의 동시성 보장을 이 짧은 본문만으로 단정하지 않습니다. 0에서 종료를 호출하면 -1이 될 수 있으며 ==0 조건을 통과하지 않습니다. 균형 계약이 필요한 이유입니다.')],
    [('카운터 2에서 종료 경로를 한 번 호출하면 로그 작업을 깨우는가?', '아니다. 카운터 1이고 console_unblank만 먼저 호출된다', '그렇다. yes=0이면 무조건 깨운다', 'wake_up_klogd는 --oops_in_progress == 0 조건 안에 있습니다. console_unblank는 그 조건 밖이라 종료 경로마다 실행됩니다.'),
     ('이 함수가 시스템의 모든 spinlock을 직접 해제하는가?', '아니다. 현재 본문은 카운터와 콘솔·로그 처리를 한다', '그렇다. 이름에 bust_spinlocks가 있으므로 모든 잠금을 푼다', '본문에는 잠금 주소 순회나 spin_unlock 호출이 없습니다. 함수 이름·주석의 목적과 실제 수행 연산을 구별해야 합니다.')])

add('lib/irq_regs.c','IRQ 레지스터 저장소 전체: CPU별 포인터와 아키텍처 fallback',
    '함수가 없는 파일도 커널의 중요한 상태 저장소를 정의할 수 있습니다.',
    'ARCH_HAS_OWN_IRQ_REGS가 정의되지 않은 빌드에서 DEFINE_PER_CPU(struct pt_regs *, __irq_regs)로 CPU별 포인터 저장소를 정의하고 EXPORT_PER_CPU_SYMBOL로 공개합니다.',
    '현재 인터럽트 문맥의 레지스터 프레임 포인터를 보관하는 저장소입니다. 레지스터 프레임을 새로 할당하거나 포인터가 가리키는 데이터를 복사하지 않습니다. 아키텍처 구현 여부와 helper는 asm/irq_regs.h를 함께 읽습니다.',
    [('파일 전체 구성','SPDX·저작권·저장소 설명, export.h·percpu.h·asm/irq_regs.h 포함, 조건부 per-CPU 정의와 export가 전부입니다. ARCH_HAS_OWN_IRQ_REGS가 있는 경우 이 fallback 저장소와 export는 전처리에서 빠집니다.'),
     ('왜 CPU별인가','서로 다른 CPU는 동시에 다른 인터럽트 프레임을 처리할 수 있습니다. 하나의 전역 포인터면 서로 덮어쓸 수 있으므로 CPU별 저장 위치를 둡니다. 저장하는 형식은 struct pt_regs 자체가 아니라 그 구조체를 가리키는 포인터입니다.'),
     ('수명과 중첩','generic helper의 set_irq_regs는 이전 포인터를 돌려주므로 중첩 진입 뒤 복구할 수 있습니다. 이 파일의 저장소 정의만으로 push/pop이 자동 실행되는 것은 아닙니다. 호출자는 현재 CPU 문맥과 이전 포인터 복구, 프레임의 수명을 지켜야 합니다. per-CPU 저장소는 객체를 영구 생존시키는 참조 획득이 아닙니다.')],
    [('ARCH_HAS_OWN_IRQ_REGS가 정의되면 이 파일의 fallback 저장소는?', '이 파일에서는 정의·export하지 않는다', '아키텍처 저장소와 별도로 무조건 하나 더 만든다', '#ifndef 조건이 정의와 export를 함께 감싸므로 아키텍처가 자체 구현을 제공하는 빌드에서는 이 블록을 제거합니다.'),
     ('__irq_regs에 저장되는 것은?', 'CPU별 struct pt_regs 포인터', '모든 CPU가 공유하는 pt_regs 구조체 하나', 'DEFINE_PER_CPU의 첫 인자가 struct pt_regs *입니다. CPU별 주소 공간 배치와 포인터가 가리키는 프레임의 실제 저장소는 다른 층위입니다.')])

add('lib/memregion.c','메모리 영역 ID 전체: IDA와 자원의 실제 소유권',
    '메모리 영역의 번호를 할당하는 것과 물리 메모리 자체를 할당하는 것은 다른 작업입니다.',
    '파일 내부 static DEFINE_IDA(memregion_ids)가 번호 사용 상태를 관리합니다. memregion_alloc은 gfp를 ida_alloc에 전달하고 결과를 그대로 반환합니다. memregion_free는 같은 IDA에 ida_free를 호출합니다.',
    '반환값이 음수면 실패입니다. 성공한 번호만 해당 수명에 맞춰 한 번 해제해야 하며 해제 후 같은 번호가 재사용될 수 있습니다. 이 파일에는 번호에서 메모리 객체를 찾는 별도 매핑이 없습니다.',
    [('전체 파일 구조','SPDX와 목적 주석, idr/types/memregion 헤더, 정적 IDA, 두 짧은 wrapper와 EXPORT_SYMBOL 두 개가 전부입니다. 함수는 별도 잠금을 구현하지 않고 IDA API의 내부 관리에 의존합니다. 외부 객체의 동시 접근까지 자동으로 보호하지는 않습니다.'),
     ('성공·실패 경로','memregion_alloc(gfp)는 ida_alloc의 결과를 가공하지 않습니다. 호출자는 id>=0인지 확인한 뒤 번호를 사용할 수 있습니다. gfp는 IDA 내부 할당의 허용 문맥을 지정하며 호출 문맥에 맞게 선택해야 합니다. memregion_free는 void이며 잘못된 id나 이중 해제를 안전한 사용으로 바꿔주는 검증 계층이 아닙니다.'),
     ('CS 연결과 ABA','번호는 식별 자원이지 메모리 영역 내용 자체가 아닙니다. A가 쓰던 id를 해제한 뒤 B가 재사용하면 오래된 id만으로 A/B를 구별할 수 없습니다. 세대 값이나 외부 객체 수명 계약이 필요한지 호출 경로에서 판단합니다. 이 파일에는 그런 세대 카운터가 없습니다.')],
    [('memregion_alloc이 음수를 반환하면?', '실패로 처리하고 유효한 영역 ID처럼 사용하지 않는다', '음수도 정상 ID라 곧바로 memregion_free에 넘긴다', 'wrapper는 ida_alloc의 오류를 그대로 전달합니다. 번호 획득 실패를 메모리 영역 생성 성공과 혼동하면 안 됩니다.'),
     ('이 함수가 물리 메모리 영역을 직접 확보하는가?', '아니다. 영역을 식별할 정수 번호를 관리한다', '그렇다. 반환값이 메모리 시작 주소다', '반환형은 int이고 구현은 IDA 할당입니다. 페이지나 물리 주소 범위를 할당·매핑하는 호출은 없습니다.'),
     ('한 번 해제한 id는 영원히 재사용되지 않는가?', '아니다. 번호가 재사용될 수 있어 객체 수명과 구별해야 한다', '그렇다. 모든 IDA 번호는 영구 고유하다', 'IDA는 현재 사용 중인 번호를 관리합니다. 해제는 재사용 가능하게 만드는 작업이며 이 wrapper에 세대 정보를 붙이는 코드는 없습니다.')])

add('lib/iommu-helper.c','IOMMU 빈 구간 할당 전체: 비트맵·정렬·경계 제한',
    '연속 빈 비트를 찾는 것만으로 장치의 주소 경계 조건이 만족되지는 않습니다.',
    'iommu_area_alloc은 size를 1 줄여 마지막 비트를 제외하고 bitmap_find_next_zero_area로 nr개 연속 빈 비트를 찾습니다. 후보가 장치 경계를 넘으면 다음 경계로 start를 옮겨 다시 찾습니다. 유효한 후보는 bitmap_set으로 예약하고 인덱스를 반환합니다.',
    'size는 마지막 슬롯을 제외하는 계약을 고려한 유효 양수여야 하며 nr도 양수이고 boundary_size 이하라는 전제가 필요합니다. boundary_size는 2의 거듭제곱, align_mask와 shift는 주소 단위와 정렬 규칙에 맞춰야 합니다. 비트맵 검색·예약 전체의 외부 동기화도 필요합니다.',
    [('전체 파일 구성과 반환값','SPDX·설명, bitmap.h와 iommu-helper.h 포함, 함수 하나가 전부입니다. 실패는 unsigned long 반환형에서 -1, 즉 ULONG_MAX로 나타납니다. 부호 없는 값을 index<0으로 검사해서는 실패를 찾을 수 없습니다. 성공 때만 bitmap_set을 호출합니다.'),
     ('검색·경계·재시도','bitmap_find_next_zero_area는 연속 0과 align_mask를 고려합니다. 추가 helper는 (shift+index)&(boundary_size-1)에 nr을 더해 boundary_size를 초과하는지 검사합니다. 예를 들어 boundary=8,shift=0,index=6,nr=3이면 6+3>8이라 start를 8로 올립니다. index=5,nr=3이면 끝이 정확히 8이므로 경계를 넘지 않습니다.'),
     ('입력 전제와 진행성','size=0이면 unsigned 감소가 큰 값으로 감겨 실제 비트맵보다 큰 검색 범위를 만들 수 있습니다. nr>boundary_size이면 경계에 정렬된 index에서도 span이 참이고 ALIGN이 같은 시작을 반환할 수 있어 재시도가 진전하지 않을 수 있습니다. 이 wrapper는 이 입력들을 먼저 검사해 오류로 반환하는 구조가 아닙니다. 유효한 caller 계약을 요구한다는 점이 핵심입니다.'),
     ('CS 연결과 경쟁','첫 적합 빈 영역 탐색, 정렬 제약, 경계 제약을 결합한 자원 할당입니다. 한 번의 검색만으로 끝나지 않을 수 있으므로 항상 O(1)이라고 설명할 수 없습니다. 검색과 bitmap_set 사이를 다른 호출과 동시에 실행하면 같은 영역을 선택할 수 있으므로 이 함수 자체에 잠금이 없다는 사실도 읽어야 합니다.')],
    [('boundary=8,shift=0,index=6,nr=3 후보는?', '경계를 넘으므로 다음 경계 start=8에서 다시 찾는다', '빈 비트 세 개면 경계와 무관하게 예약한다', '경계 내부 오프셋 6에 길이 3을 더하면 9>8입니다. 연속 비트 조건을 만족해도 장치 경계 조건이 실패합니다.'),
     ('이 함수의 unsigned long 실패값을 index<0으로 검사해도 되는가?', '아니다. -1이 unsigned 최댓값으로 변환된다', '그렇다. -1은 모든 자료형에서 음수다', 'C의 unsigned 변환으로 -1은 ULONG_MAX입니다. 반환형에 맞는 실패 sentinel 비교를 해야 합니다.'),
     ('nr>boundary_size인 호출에 대해 항상 정상 종료를 보장하는가?', '아니다. 유효한 범위 계약을 지키지 않으면 재시도가 진전하지 않을 수 있다', '그렇다. 함수가 nr을 자동으로 경계 크기로 줄인다', '코드는 nr을 줄이지 않습니다. 경계에 정렬된 후보가 여전히 경계를 넘는다면 start 계산이 같은 위치를 내놓을 수 있습니다.'),
     ('서로 다른 CPU의 검색·예약을 이 함수가 자체 잠금으로 직렬화하는가?', '아니다. 호출 경로의 동기화가 필요하다', '그렇다. bitmap_set이라는 이름이 트랜잭션을 뜻한다', '본문에 잠금이 없고 검색과 예약은 별도 호출입니다. 개별 비트 연산의 구현과 여러 단계 할당 작업의 원자성을 혼동하면 안 됩니다.')])

add('lib/net_utils.c','MAC 문자열 변환 전체: 검증 후 쓰기와 접미사 허용',
    '검증을 끝내기 전 출력 버퍼를 바꾸지 않는 파서입니다. 그러나 문자열 전체 길이 검증과 접두부 파싱은 다릅니다.',
    'mac_pton은 3*ETH_ALEN-1=17바이트의 최소 접두부 길이를 확인합니다. 첫 루프에서 여섯 바이트의 두 16진 문자와 다섯 콜론을 검증하고, 두 번째 루프에서 상위 nibble<<4와 하위 nibble을 OR해 출력합니다.',
    '입력은 필요한 길이만큼 안전하게 읽을 수 있어야 하고 출력 mac에는 ETH_ALEN 바이트 공간이 필요합니다. 함수는 s[17]이 NUL인지 검사하지 않으므로 유효한 MAC 접두부 뒤에 문자가 더 있어도 성공할 수 있습니다.',
    [('파일 전체와 helper','SPDX, string/if_ether/ctype/export/hex 헤더, 함수 하나와 export가 전부입니다. ETH_ALEN이 주소 길이 6을 정하고 strnlen은 최대 17바이트만 셉니다. isxdigit는 문자를 검증하며 hex_to_bin이 각 nibble을 값으로 바꿉니다.'),
     ('출력 보존과 단계 분리','길이가 짧거나 16진 문자가 아니거나 중간 콜론이 틀리면 첫 루프에서 false로 반환합니다. mac에 쓰는 대입은 검증 루프가 모두 끝난 뒤라 이러한 실패는 기존 출력 값을 보존합니다. 이 보장은 입력이 실행 도중 외부에서 변경되지 않는 정상 계약 아래 해석합니다.'),
     ('길이와 계산 예제','문자 A와 f는 각각 10과 15이므로 (10<<4)|15=0xAF입니다. aa:bb:cc:dd:ee:ffXYZ는 처음 17문자가 올바르고 종료 문자 검사가 없어 접두부 파싱이 성공합니다. 문자열 전체가 정확히 MAC 형식이어야 하는 호출자는 별도로 끝을 확인해야 합니다.'),
     ('CS 연결','validate-then-commit은 부분 출력 손상을 피하는 패턴입니다. 하지만 TOCTOU 관점에서 입력이 검증과 변환 사이 바뀌지 않는다는 전제도 있습니다. 고정 6바이트 파싱이므로 유효 입력의 시간·출력 공간은 상수입니다. 형식 검증이 MAC 주소의 실제 장치 소유권이나 네트워크 도달 가능성을 증명하지 않습니다.')],
    [('aa:bb:cc:dd:ee:ffXYZ는 이 함수에서 반드시 실패하는가?', '아니다. 앞 17문자가 유효하면 뒤 문자를 검사하지 않는다', '그렇다. strnlen이 전체 문자열 길이를 비교한다', 'strnlen(s,17)은 길이가 17 이상이면 17을 반환합니다. 이후 검사도 16번 인덱스까지이며 s[17]의 NUL 여부는 보지 않습니다.'),
     ('다섯 번째 주소 바이트에 잘못된 문자가 있으면 앞 네 바이트 출력은?', '검증 루프에서 실패하므로 출력은 쓰기 전 상태를 유지한다', '앞 네 바이트만 새 값으로 덮인 채 반환한다', '검증과 출력 변환이 별도 루프입니다. 모든 형식 검사를 통과하기 전에는 mac[i] 대입이 실행되지 않습니다.'),
     ('문자 Af의 출력 바이트는?', '0xAF', '0x19', 'A의 nibble 10을 네 비트 옮겨 0xA0으로 만들고 f의 15인 0x0F와 OR해 0xAF를 얻습니다. 두 nibble을 일반 덧셈 10+15만 하는 계산은 틀립니다.')])

add('lib/is_single_threaded.c','단일 스레드 판단 전체: 스레드 그룹과 mm 공유는 다르다',
    '현재 프로세스의 스레드 수만 확인하면 다른 프로세스와 주소 공간을 공유하는 경우를 놓칠 수 있습니다.',
    'current_is_single_threaded는 signal->live가 1이 아니면 false입니다. mm_users가 1이면 true로 빠르게 반환합니다. 그 외에는 RCU 아래 다른 사용자 프로세스의 스레드들을 살펴 같은 mm을 쓰는 실행 흐름이 있는지 검사합니다.',
    '함수는 current->mm을 역참조하므로 유효한 사용자 mm이 있는 호출 문맥을 전제로 읽습니다. 반환값은 객체에 영구적인 독점 소유권을 부여하지 않으며 호출자가 이후 상태 변화에 대한 규약을 지켜야 합니다.',
    [('전체 파일 구조와 빠른 경로','SPDX·설명·출처 주석, sched/signal·task·mm 헤더와 함수 하나가 전체입니다. live!=1 검사는 같은 thread group 안의 살아 있는 실행 흐름을 먼저 확인합니다. mm_users==1은 별도의 mm 사용자 수 조건이고 두 카운터는 같은 뜻이 아닙니다.'),
     ('RCU 탐색의 분기','ret=false로 시작하고 rcu_read_lock을 잡습니다. PF_KTHREAD인 그룹과 현재 group_leader는 건너뜁니다. 각 다른 그룹에서 t->mm==mm을 만나면 found로 가서 false를 유지합니다. 다른 non-NULL mm을 만나면 그 그룹의 내부 순회를 멈춥니다. t->mm==NULL이면 smp_rmb 뒤 계속 진행하여 종료 과정과 CLONE_VM 관계의 관찰 순서를 보존하려는 원문 의도를 읽습니다.'),
     ('모든 경로의 해제','끝까지 같은 mm 사용자를 못 찾으면 ret=true로 바꿉니다. 정상 완료와 goto found 모두 같은 rcu_read_unlock을 지나 반환합니다. RCU는 탐색 중 객체 수명·접근 규약의 일부이며 일반 mutex처럼 모든 대상 필드 쓰기를 정지시키는 장치가 아닙니다.'),
     ('CS 연결과 범위','thread group과 주소 공간의 공유 관계를 별도로 다루는 객체 모델입니다. 빠른 카운터 검사 뒤 필요할 때 전역 목록을 탐색하므로 항상 O(1)은 아닙니다. mm_users>1만으로 다른 살아 있는 사용자 실행 흐름이 있다고 즉시 결론 내리지 않고 실제 탐색을 하는 점도 중요합니다.')],
    [('live==1이지만 mm_users>1이면 바로 true인가?', '아니다. 다른 프로세스의 mm 공유를 탐색한다', '그렇다. thread group에 하나면 주소 공간도 독점이다', 'CLONE_VM 등으로 서로 다른 프로세스 관계에서도 mm을 공유할 수 있습니다. 함수는 두 조건을 구별하고 추가 탐색을 수행합니다.'),
     ('같은 mm을 찾고 goto found하면 RCU 잠금 해제가 생략되는가?', '아니다. found 라벨 뒤 rcu_read_unlock이 실행된다', '그렇다. 조기 탐색 성공은 해제를 생략한다', 'ret=false인 채 공통 해제 지점으로 이동합니다. 조기 종료와 자원 해제를 함께 배치하는 제어 흐름입니다.'),
     ('반환 true가 이후에도 영구적으로 mm 독점임을 보장하는가?', '아니다. 호출 문맥과 이후 변화에 대한 별도 계약이 필요하다', '그렇다. 함수가 이후 fork와 clone을 금지한다', '본문에는 영구 독점 잠금 획득이나 새 작업 생성 금지가 없습니다. 상태를 관찰하는 함수와 미래 상태를 제한하는 기능을 구별해야 합니다.')])

add('lib/debug_locks.c','잠금 디버깅 상태 전체: 첫 오류와 원자적 끄기',
    '첫 잠금 오류 뒤에 파생 오류 로그가 쏟아지는 것을 줄이기 위한 공통 상태입니다.',
    'debug_locks는 1로 시작하고 debug_locks_silent는 정적 초기값 0입니다. debug_locks_off는 debug_locks가 켜져 있고 __debug_locks_off가 이전 비영 값을 반환한 경우에만 안쪽으로 갑니다. silent가 아니면 console_verbose를 호출하고 1을 반환합니다.',
    '__debug_locks_off의 실제 연산은 헤더의 xchg(&debug_locks,0)입니다. 반환값 0이 반드시 아무 상태 변화도 없었다는 뜻은 아닙니다. silent가 켜져 있으면 디버깅 상태를 껐어도 0을 반환합니다.',
    [('전체 파일 구성','SPDX·저작권·목적 주석과 rwsem/mutex/export/spinlock/debug_locks 헤더, __read_mostly 전역 두 개, GPL export 세 개, 함수 하나가 전체입니다. __read_mostly는 배치·접근 특성 힌트이며 값을 상수로 만들거나 동기화하는 키워드가 아닙니다.'),
     ('첫 호출과 후속 호출','debug_locks=1,silent=0이면 원자 교환이 1을 돌려주고 상태는 0이 됩니다. console_verbose 후 1을 반환합니다. 뒤 호출은 꺼진 상태를 보거나 xchg에서 이전 0을 받아 0을 반환합니다. 바깥의 읽기 검사만을 원자적 승자 결정으로 해석하지 말고 xchg의 이전값을 확인합니다.'),
     ('silent 분기','debug_locks=1,silent=1에서도 xchg는 실행되어 debug_locks=0으로 바뀝니다. 하지만 console_verbose와 return 1은 생략되어 최종 0입니다. 실제 잠금의 소유권이나 locked 상태를 해제하는 동작이 아니라 디버그 보고 상태를 제어하는 것입니다.'),
     ('CS 연결','공유 플래그를 원자적으로 바꾸면서 이전 상태를 받아 한 실행 흐름만 특정 후속 작업을 맡기는 패턴입니다. 함수 반환값을 API 의미대로 읽어야 하며 bool처럼 보이는 int 값이 모든 부수 효과 유무를 표현한다고 단정하면 안 됩니다.')],
    [('debug_locks=1,silent=1에서 debug_locks_off 후 상태·반환값은?', '상태 0, 반환 0', '상태 1, 반환 0', 'silent 검사는 xchg 뒤에 있습니다. 출력은 조용해도 전역 디버그 상태는 이미 꺼집니다.'),
     ('이전 상태를 얻으며 debug_locks를 0으로 만드는 연산은?', '헤더 helper의 xchg', '__read_mostly 지정자', '__read_mostly는 원자 연산이 아닙니다. __debug_locks_off가 xchg(&debug_locks,0)를 호출해 이전값과 교환을 결합합니다.'),
     ('이 함수가 실제 mutex나 spinlock을 unlock하는가?', '아니다. 잠금 디버깅 보고 상태를 끈다', '그렇다. 모든 잠금 소유권을 제거한다', '인자로 잠금 객체를 받지 않고 전역 디버그 플래그만 갱신합니다. 오류 보고 장치와 실제 동기화 상태를 구별해야 합니다.')])

add('lib/list_debug.c','연결 리스트 검증 전체: 이웃 불변식과 단락 평가',
    '양방향 리스트를 안전하게 조작하려면 next와 prev가 서로 일치해야 합니다. 검증 함수가 검사하지 않는 범위도 함께 읽습니다.',
    '__list_add_valid_or_report는 prev/next의 NULL, 서로의 역방향 링크, new가 바로 이웃과 같은지를 검사합니다. __list_del_entry_valid_or_report는 entry의 이웃을 읽고 NULL·poison·역방향 연결을 검사합니다. 감지된 손상은 보고 후 false, 통과는 true입니다.',
    '이 함수들은 검증·오류 보고이며 실제 링크 수정이나 메모리 해제를 하지 않습니다. 유효하게 읽을 수 있는 객체와 호출 경로의 동기화가 전제입니다. 전역 리스트를 전부 순회해 모든 중복을 찾는 검사도 아닙니다.',
    [('파일 전체 구성','저작권·GPL 설명, export/list/bug/kernel/rculist 헤더와 두 __list_valid_slowpath 함수, 각 EXPORT_SYMBOL이 전체입니다. CHECK_DATA_CORRUPTION의 실제 진단 또는 중단 동작은 구성과 매크로 정의에 의존합니다. 이 함수는 오류가 보고 후 복귀하는 경우 false를 반환하는 구조입니다.'),
     ('삽입 검증 순서','prev==NULL 또는 next==NULL이 참이면 || 단락 평가로 뒤의 역참조 검사를 실행하지 않습니다. 이후 next->prev==prev와 prev->next==next가 필요합니다. 마지막 new==prev||new==next는 인접 노드와 같은 객체를 바로 삽입하는 실수를 찾지만 new가 멀리 떨어진 다른 리스트에 연결되어 있는지 전체 검색하지는 않습니다.'),
     ('삭제 검증 순서','먼저 entry->prev와 entry->next를 지역 변수에 읽으므로 entry 자체가 유효해야 합니다. 그 뒤 next/prev NULL, LIST_POISON1/2, prev->next 및 next->prev가 entry를 가리키는지 검사합니다. entry==NULL을 먼저 막는 코드가 없는 점과 이웃 NULL 검사가 있다는 점은 다릅니다.'),
     ('CS 연결과 검사의 한계','양방향 링크의 지역 불변식 검사로 메모리 손상을 조기에 드러냅니다. 시간은 검사 몇 개의 O(1)이며 리스트 전체의 무순환성·소유권·동시 변경 부재를 증명하지 않습니다. 임의의 잘못된 non-NULL 포인터를 무조건 안전하게 역참조할 수 있는 주소 검증기가 아닙니다.')],
    [('삽입 검사에서 prev가 NULL이면 곧바로 prev->next를 읽는가?', '아니다. 앞 조건이 참이면 ||가 뒤 조건 평가를 생략한다', '그렇다. ||는 모든 조건을 항상 평가한다', 'C의 논리 OR는 왼쪽부터 평가하며 참이면 나머지를 실행하지 않습니다. 이 순서가 NULL 검사 뒤 역참조를 두는 의미입니다.'),
     ('삭제 검사에 entry=NULL을 전달해도 이웃 NULL 검사로 보호되는가?', '아니다. 검사 전에 entry->prev/next를 먼저 읽는다', '그렇다. 모든 NULL을 무조건 안전하게 거절한다', 'entry 자체의 유효성 검사가 없습니다. 지역 변수 초기화 시 이미 역참조하므로 호출자 계약이 필요합니다.'),
     ('삽입 검사를 통과하면 new가 어디에도 연결되지 않았음을 증명하는가?', '아니다. 직접 이웃과 같은지만 확인하며 전역 목록은 순회하지 않는다', '그렇다. 모든 리스트를 자동 검색한다', 'new==prev 또는 new==next만 검사합니다. 제한된 지역 검사를 전역 소유권 검증으로 확대 해석하면 안 됩니다.')])
